class Song { public string Name,Artist,Album,Url,Kind,Id,Artwork; public string Key {get{Uri u;string country="";if(Uri.TryCreate(Url,UriKind.Absolute,out u)){string[] parts=u.AbsolutePath.Trim('/').Split('/');if(parts.Length>0&&parts[0].Length==2)country=parts[0].ToLowerInvariant();}return (Kind??"")+"|"+country+"|"+(!String.IsNullOrEmpty(Id)?Id:(Url??""));}} public override string ToString(){return Name+"  —  "+Artist+"   ·   "+Album;} }
