static class HistoryStore {
 public static string PathName {get{return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"MusicHelper","download-history.jsonl");}}
 public static void Append(string file,HistoryRecord record){
  Directory.CreateDirectory(Path.GetDirectoryName(file));string line=new JavaScriptSerializer().Serialize(record)+Environment.NewLine;
  using(var gate=new Mutex(false,@"Local\FreeMusicDownloadHistory")){bool held=false;try{try{held=gate.WaitOne(5000);}catch(AbandonedMutexException){held=true;}if(!held)throw new IOException("下载历史文件正被其他程序使用。");using(var stream=new FileStream(file,FileMode.Append,FileAccess.Write,FileShare.Read)){byte[] bytes=new UTF8Encoding(false).GetBytes(line);stream.Write(bytes,0,bytes.Length);stream.Flush();}}finally{if(held)gate.ReleaseMutex();}}
 }
 public static List<HistoryRecord> Read(string file){
  var list=new List<HistoryRecord>();if(!File.Exists(file))return list;
  using(var stream=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite))using(var reader=new StreamReader(stream,Encoding.UTF8)){var serializer=new JavaScriptSerializer();string line;while((line=reader.ReadLine())!=null){if(String.IsNullOrWhiteSpace(line))continue;try{var item=serializer.Deserialize<HistoryRecord>(line);if(item!=null&&!String.IsNullOrEmpty(item.Name))list.Add(item);}catch(Exception){}}}
  list.Reverse();return list;
 }
}
