 public static void Initialize(){using(var stream=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("MusicHelper.PingFang.ttf")){if(stream==null){Family=SystemFonts.MessageBoxFont.FontFamily;return;}byte[] bytes=new byte[checked((int)stream.Length)];int offset=0,n;while(offset<bytes.Length&&(n=stream.Read(bytes,offset,bytes.Length-offset))>0)offset+=n;if(offset!=bytes.Length)throw new Exception("界面字体读取不完整。");memory=Marshal.AllocHGlobal(bytes.Length);Marshal.Copy(bytes,0,memory,bytes.Length);fonts.AddMemoryFont(memory,bytes.Length);uint count=0;if(AddFontMemResourceEx(memory,(uint)bytes.Length,IntPtr.Zero,ref count)==IntPtr.Zero||fonts.Families.Length==0)throw new Exception("无法加载界面字体。");Family=fonts.Families[0];}}
