 void SyncVisibleSelection(){var changes=new Dictionary<string,bool>(StringComparer.OrdinalIgnoreCase);for(int i=0;i<results.Items.Count;i++){var song=results.Items[i] as Song;if(song==null)continue;bool previous;visibleSelections.TryGetValue(song,out previous);bool current=results.GetSelected(i);if(current!=previous)changes[song.Key]=current;}if(changes.Count==0)return;foreach(var change in changes){if(change.Value)selectedItems.Add(change.Key);else selectedItems.Remove(change.Key);}rendering=true;try{for(int i=0;i<results.Items.Count;i++){var song=results.Items[i] as Song;if(song==null)continue;bool current=selectedItems.Contains(song.Key);if(results.GetSelected(i)!=current)results.SetSelected(i,current);visibleSelections[song]=current;}}finally{rendering=false;}}
 void RenderResults(){pendingVisible.Clear();if(listUpdateTimer!=null)listUpdateTimer.Stop();rendering=true;try{results.BeginUpdate();results.Items.Clear();visibleSelections.Clear();var source=inAlbum?albumItems:searchItems;foreach(var item in source)if(inAlbum||filter=="all"||item.Kind==filter)results.Items.Add(item);for(int i=0;i<results.Items.Count;i++){var song=(Song)results.Items[i];bool selected=selectedItems.Contains(song.Key);if(selected)results.SetSelected(i,true);visibleSelections[song]=selected;}results.EndUpdate();}finally{rendering=false;}status.Text=inAlbum?albumTitle+"  ·  "+results.Items.Count+" 首":"搜索结果  ·  "+results.Items.Count+" 项"+(pagingSearch?"（继续加载中）":"");empty.Visible=results.Items.Count==0;empty.Text=inAlbum?"专辑没有可显示的歌曲。":"当前分类没有结果\n\n试试其他分类或关键词。";helper.Text=inAlbum?"勾选歌曲下载，或点击全选下载整张专辑。":"搜索结果可能不含歌手全部作品；点击专辑名称查看曲目。";filterAll.Visible=filterSongs.Visible=filterAlbums.Visible=!inAlbum;backResults.Visible=inAlbum;foreach(var pair in new[]{new KeyValuePair<Button,string>(filterAll,"all"),new KeyValuePair<Button,string>(filterSongs,"songs"),new KeyValuePair<Button,string>(filterAlbums,"albums")}){((SoftButton)pair.Key).Primary=pair.Value==filter;pair.Key.Invalidate();}UpdateButtons();}
 void FlushPendingResults(){if(pendingVisible.Count==0){listUpdateTimer.Stop();return;}if(inAlbum||busy||searching||(DateTime.UtcNow-lastListInteraction).TotalMilliseconds<900)return;int top=results.Items.Count>0?results.TopIndex:0;rendering=true;try{results.BeginUpdate();foreach(var item in pendingVisible)if(filter=="all"||item.Kind==filter){int index=results.Items.Add(item);bool selected=selectedItems.Contains(item.Key);if(selected)results.SetSelected(index,true);visibleSelections[item]=selected;}pendingVisible.Clear();if(results.Items.Count>0&&top<results.Items.Count&&results.TopIndex!=top)results.TopIndex=top;results.EndUpdate();}finally{rendering=false;}empty.Visible=results.Items.Count==0;status.Text="搜索结果  ·  "+results.Items.Count+" 项"+(pagingSearch?"（继续加载中）":"");listUpdateTimer.Stop();UpdateButtons();}
