 string Fetch(string url,string bearer=null){using(var wc=new WebClient()){wc.Encoding=Encoding.UTF8;wc.Headers[HttpRequestHeader.UserAgent]="Mozilla/5.0";wc.Headers["Origin"]="https://music.apple.com";wc.Headers[HttpRequestHeader.Referer]="https://music.apple.com/";if(bearer!=null)wc.Headers[HttpRequestHeader.Authorization]="Bearer "+bearer;return wc.DownloadString(url);}}
 string Token(string country){if(token!="")return token;var urls=new Queue<string>();var seen=new HashSet<string>();string page=Fetch("https://music.apple.com/"+country+"/browse"); urls.Enqueue("https://music.apple.com/"+country+"/browse"); int n=0;while(urls.Count>0&&n<32){string url=urls.Dequeue();if(!seen.Add(url))continue;string text=n++==0?page:Fetch(url);foreach(Match m in Regex.Matches(text,@"eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+")){try{string p=m.Value.Split('.')[1].Replace('-','+').Replace('_','/');p=p.PadRight((p.Length+3)/4*4,'=');var j=(Dictionary<string,object>)new JavaScriptSerializer().DeserializeObject(Encoding.UTF8.GetString(Convert.FromBase64String(p)));if(j.ContainsKey("exp")&&Convert.ToInt64(j["exp"])>DateTimeOffset.UtcNow.ToUnixTimeSeconds()+60){token=m.Value;return token;}}catch{}}
