 string SearchPages(string term,string country,IProgress<List<Song>> progress,CancellationToken cancellation){var unique=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var paths=new HashSet<string>();var pending=new Queue<KeyValuePair<string,string>>();string bearer=Token(country);foreach(string kind in new[]{"songs","albums"})pending.Enqueue(new KeyValuePair<string,string>(kind,"/v1/catalog/"+country+"/search?types="+kind+"&limit=40&term="+Uri.EscapeDataString(term)));int pages=0;while(pending.Count>0){cancellation.ThrowIfCancellationRequested();var current=pending.Dequeue();string path=current.Value,kind=current.Key;if(!path.StartsWith("/v1/catalog/"+country+"/search?",StringComparison.Ordinal)||!paths.Add(path)||++pages>200)return "后续分页无法继续读取，以下为已获取的结果。";try{var root=Object(new JavaScriptSerializer().DeserializeObject(Fetch("https://amp-api.music.apple.com"+path,bearer)));cancellation.ThrowIfCancellationRequested();object grouped,raw;var page=new List<Song>();string next="";if(root!=null&&root.TryGetValue("results",out grouped)&&Object(grouped)!=null&&Object(grouped).TryGetValue(kind,out raw)){var group=Object(raw);foreach(object item in Items(group,"data")){var song=ReadSong(item,kind);if(song!=null&&unique.Add(kind+":"+song.Url))page.Add(song);}next=Get(group,"next");}progress.Report(page);if(next!="")pending.Enqueue(new KeyValuePair<string,string>(kind,next));}catch(OperationCanceledException){throw;}catch(Exception ex){if(unique.Count==0)throw;return "部分结果加载失败："+ex.Message;}}return "";}
 async void Search(){if(busy||searching)return;string term=query.Text.Trim();if(term.Length==0){helper.Text="请输入歌曲、歌手、专辑或 Apple Music 链接。";return;}if(searchCancellation!=null)searchCancellation.Cancel();var source=new CancellationTokenSource();searchCancellation=source;int generation=++searchGeneration;bool isLink=term.IndexOf("://",StringComparison.Ordinal)>=0, firstPage=false;pendingVisible.Clear();listUpdateTimer.Stop();searchItems.Clear();albumItems.Clear();inAlbum=false;rendering=true;results.Items.Clear();rendering=false;pagingSearch=!isLink;searching=true;UpdateButtons();status.Text="正在查找…";empty.Text="正在查找，请稍候…";empty.Visible=true;string country=region.SelectedItem.ToString().Split(' ')[1].ToLowerInvariant();var progress=new Progress<List<Song>>(page=>{if(IsDisposed||generation!=searchGeneration||source.IsCancellationRequested)return;searchItems.AddRange(page);if(!firstPage){firstPage=true;searching=false;RenderResults();}else if(!inAlbum){pendingVisible.AddRange(page);if(pendingVisible.Count>0)listUpdateTimer.Start();}});try{if(isLink){var items=await Task.Run(()=>ResolveCollection(term));if(generation!=searchGeneration)return;searchItems=items;filter="all";pagingSearch=false;searching=false;RenderResults();}else{string warning=await Task.Run(()=>SearchPages(term,country,progress,source.Token));if(generation!=searchGeneration)return;pagingSearch=false;if(!firstPage){searching=false;RenderResults();}else if(!inAlbum&&!busy&&!searching)status.Text="搜索结果  ·  "+results.Items.Count+" 项"+(pendingVisible.Count>0?"（正在整理结果）":"");if(warning!=""&&!inAlbum&&!busy)helper.Text=warning;}}catch(OperationCanceledException){}catch(Exception ex){if(generation!=searchGeneration)return;token="";pagingSearch=false;if(!firstPage){searching=false;status.Text="查找未完成";empty.Text="无法读取\n\n请检查链接、地区和网络后重试。";empty.Visible=true;}if(!inAlbum&&!busy)helper.Text=firstPage?"部分结果加载失败："+ex.Message:ex.Message;Debug.WriteLine(ex);}finally{if(generation==searchGeneration){if(!firstPage)searching=false;pagingSearch=false;searchCancellation=null;UpdateButtons();}source.Dispose();}}
