 string PrepareGuiSetup(){string source=Path.Combine(engine,"scripts","wrappers"), target=Path.Combine(engine,"scripts","wrappers-gui");CopyDirectory(source,target);string modules=Path.Combine(target,"modules");using(var resource=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("MusicHelper.GuiPrompt.ps1")){if(resource==null)throw new Exception("缺少登录界面组件。");using(var reader=new StreamReader(resource,Encoding.UTF8))File.WriteAllText(Path.Combine(modules,"GuiPrompt.ps1"),reader.ReadToEnd(),new UTF8Encoding(true));}using(var font=System.Reflection.Assembly.GetExecutingAssembly().GetManifestResourceStream("MusicHelper.PingFang.ttf")){if(font!=null){using(var targetFont=File.Create(Path.Combine(modules,"MusicHelper.PingFang.ttf")))font.CopyTo(targetFont);}else{string stale=Path.Combine(modules,"MusicHelper.PingFang.ttf");if(File.Exists(stale))File.Delete(stale);}}foreach(string name in new[]{"Qemu.psm1","Docker.psm1"}){string path=Path.Combine(modules,name);string text=File.ReadAllText(path);if(!text.Contains("Read-Host 'Apple ID email'")||!text.Contains("Read-Host 'Apple verification code'"))throw new Exception("后台版本不兼容，无法安全启动图形登录。");File.WriteAllText(path,". (Join-Path $PSScriptRoot 'GuiPrompt.ps1')\r\n"+text,new UTF8Encoding(true));}return Path.Combine(target,"setup-qemu.ps1");}
