 string ExplainSetupFailure(string output,bool retriedQemu){if(output.IndexOf("login console disconnected",StringComparison.OrdinalIgnoreCase)>=0)return "后台在登录验证阶段断开了连接，尚不能确定是账户验证还是后台兼容性导致。请检查账号验证提示后重试；本次没有自动安装 WSL 或 Docker。";if(output.IndexOf("WSL installation",StringComparison.OrdinalIgnoreCase)>=0||output.IndexOf("WSL 2",StringComparison.OrdinalIgnoreCase)>=0)return "后台尝试准备 WSL 2 时失败。请检查系统提示或管理员授权；程序不会把这项失败当作密码错误。";if(output.IndexOf("sign-in failed",StringComparison.OrdinalIgnoreCase)>=0||output.IndexOf("verification",StringComparison.OrdinalIgnoreCase)>=0)return "账户验证未完成。请确认设备上的验证请求、验证码和订阅状态后重试。";return retriedQemu?"QEMU 后台未能完成配置或登录。请检查网络和系统授权后重试；本次没有自动切换到 Docker。":"后台配置未完成。请检查网络、系统授权和登录验证；如果系统要求重启，请重启后重试。";}
 async Task Setup(){if(busy||!File.Exists(Bridge))return;busy=true;UpdateButtons();accountStatus.Text="正在准备登录环境…";helper.Text="首次配置可能需要联网、授权或重启。";try{string script=PrepareGuiSetup();bool retryQemu=RetryQemu();string output="";int code=await Task.Run(()=>{var si=new ProcessStartInfo{FileName=Path.Combine(Environment.SystemDirectory,"WindowsPowerShell","v1.0","powershell.exe"),Arguments="-NoLogo -NoProfile -STA -ExecutionPolicy Bypass -File \""+script+"\""+(retryQemu?" -Backend qemu -Acceleration whpx":""),WorkingDirectory=engine,UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};using(var p=Process.Start(si)){var lines=new StringBuilder();object gate=new object();DataReceivedEventHandler collect=(s,e)=>{if(e.Data!=null)lock(gate){if(lines.Length<32000)lines.AppendLine(e.Data);}};p.OutputDataReceived+=collect;p.ErrorDataReceived+=collect;p.BeginOutputReadLine();p.BeginErrorReadLine();p.WaitForExit(Int32.MaxValue);lock(gate)output=lines.ToString();return p.ExitCode;}});if(code!=0){accountStatus.Text="登录或配置未完成";Notice.Show(ExplainSetupFailure(output,retryQemu),"未完成");}else{accountStatus.Text="登录完成，正在检查…";}}catch(Exception ex){Notice.Show(ex.Message,"无法启动登录");}finally{busy=false;}await Check();}
 string RunBridge(string operation,string url,string path,Action<Dictionary<string,object>> onProgress=null,string requestedQuality="ALAC"){var req=new Dictionary<string,object>{{"version",1},{"request_id",Guid.NewGuid().ToString("N")},{"operation",operation},{"wrapper","applemusicdecrypt"},{"settings",new Dictionary<string,object>{{"alac-save-folder",path},{"aac-save-folder",path},{"language","zh-CN"}}}};if(url!=null){req["url"]=url;req["quality"]=requestedQuality;}var si=new ProcessStartInfo{FileName=Bridge,WorkingDirectory=engine,UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true,StandardOutputEncoding=Encoding.UTF8,StandardErrorEncoding=UTF8Encoding.UTF8};si.EnvironmentVariables["NO_PROXY"]="localhost,127.0.0.1,::1";si.EnvironmentVariables["no_proxy"]="localhost,127.0.0.1,::1";using(var p=Process.Start(si)){p.ErrorDataReceived+=(s,e)=>{};p.BeginErrorReadLine();byte[] bytes=Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(req));p.StandardInput.BaseStream.Write(bytes,0,bytes.Length);p.StandardInput.BaseStream.Close();var response=new StringBuilder();string line;while((line=p.StandardOutput.ReadLine())!=null){response.AppendLine(line);if(onProgress!=null)try{var record=Object(new JavaScriptSerializer().DeserializeObject(line));if(record!=null&&Get(record,"event")=="progress")onProgress(record);}catch(Exception ex){Debug.WriteLine(ex.Message);}}p.WaitForExit();return response.ToString();}}
 bool Success(string response){foreach(string line in response.Split('\n'))try{var d=(Dictionary<string,object>)new JavaScriptSerializer().DeserializeObject(line);if(Get(d,"event")=="complete")return d.ContainsKey("success")&&(bool)d["success"];}catch{}return false;}
 HashSet<string> ProbeCodecs(string response,Song song){foreach(string line in response.Split('\n'))try{var serializer=new JavaScriptSerializer{MaxJsonLength=8388608,RecursionLimit=128};var record=Object(serializer.DeserializeObject(line));if(Get(record,"event")!="metadata")continue;object raw;if(!record.TryGetValue("data",out raw))continue;var data=Object(raw);var tracks=new List<Dictionary<string,object>>();foreach(var item in Items(data,"tracks")){var track=Object(item);if(track!=null)tracks.Add(track);}foreach(var track in tracks){object info;var identity=track.TryGetValue("trackData",out info)?Object(info):null;if(tracks.Count>1&&!String.IsNullOrEmpty(song.Id)&&Get(identity,"id")!=song.Id)continue;var codecs=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var codec in Items(track,"availableCodecs"))codecs.Add(Convert.ToString(codec));return codecs;}}catch(Exception ex){Debug.WriteLine(ex.Message);}return null;}
 string DetectOutputCodec(string response,string folder){string path="";foreach(string line in response.Split('\n'))try{var record=Object(new JavaScriptSerializer{MaxJsonLength=8388608}.DeserializeObject(line));if(Get(record,"event")!="artifact")continue;object raw;if(record.TryGetValue("data",out raw))path=Get(Object(raw),"path");}catch{}if(String.IsNullOrEmpty(path))return "";try{string root=Path.GetFullPath(folder).TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar)+Path.DirectorySeparatorChar;string file=Path.GetFullPath(path);if(!file.StartsWith(root,StringComparison.OrdinalIgnoreCase)||!File.Exists(file))return "";string binary=Path.Combine(engine,"tools","ffmpeg.exe");if(!File.Exists(binary))return "";var si=new ProcessStartInfo{FileName=binary,Arguments="-hide_banner -i \""+file+"\"",UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true,RedirectStandardOutput=true,StandardErrorEncoding=Encoding.UTF8};using(var process=Process.Start(si)){var log=new StringBuilder();process.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)lock(log){if(log.Length<50000)log.AppendLine(e.Data);}};process.OutputDataReceived+=(s,e)=>{};process.BeginErrorReadLine();process.BeginOutputReadLine();if(!process.WaitForExit(10000)){try{process.Kill();}catch{}return "";}process.WaitForExit();string text;lock(log)text=log.ToString();var match=Regex.Match(text,@"Audio:\s*(alac|aac)\b",RegexOptions.IgnoreCase);return match.Success?match.Groups[1].Value.ToUpperInvariant():"";}}catch{return "";}}
 string MotionAlbumId(Song song,out string country){
  country="";Uri url;if(!Uri.TryCreate(song.Url,UriKind.Absolute,out url)||url.Scheme!="https"||!String.Equals(url.Host,"music.apple.com",StringComparison.OrdinalIgnoreCase))return "";
  var parts=url.AbsolutePath.Trim('/').Split('/');if(parts.Length<3||!Regex.IsMatch(parts[0],@"^[A-Za-z]{2}$"))return "";country=parts[0].ToLowerInvariant();
  string last=parts[parts.Length-1];if(parts[1]=="album"&&Regex.IsMatch(last,@"^\d+$"))return last;
  if(!Regex.IsMatch(song.Id??"", @"^\d+$"))return "";
  var root=Object(new JavaScriptSerializer{MaxJsonLength=8388608}.DeserializeObject(Fetch("https://amp-api.music.apple.com/v1/catalog/"+country+"/songs/"+song.Id+"?include=albums",Token(country))));
  foreach(object raw in Items(root,"data")){var item=Object(raw);object relationships,albums;if(item!=null&&item.TryGetValue("relationships",out relationships)&&Object(relationships)!=null&&Object(relationships).TryGetValue("albums",out albums))foreach(object album in Items(Object(albums),"data")){string id=Get(Object(album),"id");if(Regex.IsMatch(id,@"^\d+$"))return id;}}
  return "";
 }
 string AudioArtifact(string response,string folder,Song song){
  foreach(string line in response.Split('\n'))try{var item=Object(new JavaScriptSerializer{MaxJsonLength=8388608}.DeserializeObject(line));object data;if(Get(item,"event")!="artifact"||!item.TryGetValue("data",out data))continue;string path=Get(Object(data),"path");if(String.IsNullOrEmpty(path))continue;string full=Path.GetFullPath(path);string root=Path.GetFullPath(folder).TrimEnd(Path.DirectorySeparatorChar,Path.AltDirectorySeparatorChar)+Path.DirectorySeparatorChar;if(full.StartsWith(root,StringComparison.OrdinalIgnoreCase)&&File.Exists(full)&&String.Equals(Path.GetExtension(full),".m4a",StringComparison.OrdinalIgnoreCase))return full;}catch{}
  // Existing tracks can be skipped without an artifact event. Match metadata before using any file.
  if(song==null||String.IsNullOrEmpty(song.Name)||String.IsNullOrEmpty(song.Album)||String.IsNullOrEmpty(song.Artist))return "";
  string binary=Path.Combine(engine,"tools","ffmpeg.exe");if(!File.Exists(binary))return "";
  string found="";int inspected=0;foreach(string file in Directory.EnumerateFiles(folder,"*.m4a",SearchOption.AllDirectories)){
   string title=Regex.Replace(Path.GetFileNameWithoutExtension(file),@"^\d+[.\- ]+","");if(!String.Equals(title,song.Name,StringComparison.OrdinalIgnoreCase))continue;if(++inspected>25)return "";
   var info=new ProcessStartInfo{FileName=binary,Arguments="-hide_banner -i \""+file+"\"",UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true};using(var p=Process.Start(info)){string log=p.StandardError.ReadToEnd();if(!p.WaitForExit(10000)){try{p.Kill();}catch{}continue;}var fields=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(Match m in Regex.Matches(log,@"(?m)^\s*(title|artist|album)\s*:\s*(.*?)\s*$"))if(!fields.ContainsKey(m.Groups[1].Value))fields[m.Groups[1].Value]=m.Groups[2].Value;
    string name,artist,album;if(fields.TryGetValue("title",out name)&&fields.TryGetValue("artist",out artist)&&fields.TryGetValue("album",out album)&&String.Equals(name,song.Name,StringComparison.OrdinalIgnoreCase)&&String.Equals(artist,song.Artist,StringComparison.OrdinalIgnoreCase)&&String.Equals(album,song.Album,StringComparison.OrdinalIgnoreCase)){if(found!="")return "";found=file;}}
  }return found;
 }
 string SaveMotionArtwork(Song song,string response,string folder,Dictionary<string,string> cache){
  string country;string album=MotionAlbumId(song,out country);if(album=="")return "动态封面：无法确定专辑";
  string path=AudioArtifact(response,folder,song);if(path=="")return "动态封面：未找到歌曲文件";
  string target=Path.Combine(Path.GetDirectoryName(path),"cover-motion-"+album+".mp4");if(File.Exists(target)&&new FileInfo(target).Length>0)return "动态封面：已存在";
  string key=country+"/"+album,master;
  if(!cache.TryGetValue(key,out master)){
   var root=Object(new JavaScriptSerializer{MaxJsonLength=8388608}.DeserializeObject(Fetch("https://amp-api.music.apple.com/v1/catalog/"+country+"/albums/"+album+"?extend=editorialVideo",Token(country))));
   Dictionary<string,object> videos=null;foreach(object raw in Items(root,"data")){var item=Object(raw);object attributes,editorial;if(item!=null&&item.TryGetValue("attributes",out attributes)&&Object(attributes)!=null&&Object(attributes).TryGetValue("editorialVideo",out editorial))videos=Object(editorial);break;}
   master="";if(videos!=null){foreach(string name in new[]{"motionSquareVideo1x1","motionDetailSquare","motionSquareVideo","motionDetailTall"}){object value;if(videos.TryGetValue(name,out value)){master=Get(Object(value),"video");if(master!="")break;}}if(master=="")foreach(var value in videos.Values){master=Get(Object(value),"video");if(master!="")break;}}
   cache[key]=master;
  }
  if(master=="")return "无动态封面";
  Uri remote;if(!Uri.TryCreate(master,UriKind.Absolute,out remote)||remote.Scheme!="https"||!(remote.Host.EndsWith(".mzstatic.com",StringComparison.OrdinalIgnoreCase)||remote.Host.EndsWith(".apple.com",StringComparison.OrdinalIgnoreCase))||master.IndexOfAny(new[]{'"','\r','\n'})>=0)throw new Exception("动态封面地址无效");
  string ffmpeg=Path.Combine(engine,"tools","ffmpeg.exe");if(!File.Exists(ffmpeg))throw new Exception("缺少视频处理组件");
  string temporary=Path.Combine(Path.GetDirectoryName(target),".motion-"+Guid.NewGuid().ToString("N")+".mp4");
  try{var info=new ProcessStartInfo{FileName=ffmpeg,Arguments="-nostdin -hide_banner -loglevel error -protocol_whitelist https,http,httpproxy,tls,tcp,crypto -i \""+master+"\" -map 0:v:0 -c copy -an -movflags +faststart -y \""+temporary+"\"",UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true};
   using(var p=Process.Start(info)){p.ErrorDataReceived+=(s,e)=>{};p.BeginErrorReadLine();if(!p.WaitForExit(90000)){try{p.Kill();}catch{}throw new Exception("动态封面下载超时");}p.WaitForExit();if(p.ExitCode!=0||!File.Exists(temporary)||new FileInfo(temporary).Length==0)throw new Exception("动态封面下载失败");}
   if(!File.Exists(target))File.Move(temporary,target);return "动态封面：已保存";
  }finally{try{if(File.Exists(temporary))File.Delete(temporary);}catch{}}
 }
 string Failure(string response){foreach(string line in response.Split('\n'))try{var d=(Dictionary<string,object>)new JavaScriptSerializer().DeserializeObject(line);if(Get(d,"event")=="error"){string code=Get(d,"code");if(code=="wrapper_unavailable")return "后台尚未启动。请在设置中登录并重新检查状态。";if(code=="authentication_required")return "后台尚未登录。请在设置中使用有订阅的账户完成验证。";if(code=="network_error")return "连接失败，请检查网络后重试。";return "后台返回错误："+Get(d,"message");}}catch{}return "后台未返回成功状态。";}
