 async Task Download(){
  if(queueRunning){StopQueue();return;}if(busy||searching||results.SelectedItems.Count==0)return;if(!File.Exists(Bridge)){Notice.Show("请先安装组件并完成登录。","还需准备");return;}
  string requestedQuality=quality.Value;var selected=new List<Song>();foreach(object item in results.SelectedItems){var song=item as Song;if(song!=null)selected.Add(song);}busy=true;queueRunning=true;cancelQueue=false;UpdateButtons();EnsureQueue();queueList.Items.Clear();ShowQueue();RefreshQueue();var pending=new List<DownloadEntry>();int completed=0,failed=0,skippedCount=0,attempted=0;historySaveFailed=false;var motionCache=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
  try{Directory.CreateDirectory(output);var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(var item in selected){if(cancelQueue)break;if(item.Kind=="albums"){status.Text="正在读取专辑："+item.Name;helper.Text="正在准备曲目列表…";queueSummary.Text="正在读取专辑："+item.Name;try{var tracks=await Task.Run(()=>ResolveCollection(item.Url));foreach(var track in tracks)if(seen.Add(track.Key)){var entry=new DownloadEntry{Song=track};pending.Add(entry);queueList.Items.Add(entry);}}catch(Exception ex){var entry=new DownloadEntry{Song=item,State="失败",Error="专辑读取失败："+ex.Message};queueList.Items.Add(entry);failed++;RecordHistory(entry,output);}RefreshQueue();}else if(seen.Add(item.Key)){var entry=new DownloadEntry{Song=item};pending.Add(entry);queueList.Items.Add(entry);RefreshQueue();}}
   for(int i=0;i<pending.Count&&!cancelQueue;i++){var entry=pending[i];var song=entry.Song;entry.State="下载中";entry.Phase="准备中";entry.Percent=null;status.Text="正在下载 "+(i+1)+" / "+pending.Count;helper.Text=song.Name+"  —  "+song.Artist;attempted++;RefreshQueue();bool trackError=false,skipped=false;try{entry.Phase="检查音质";RefreshQueue();string probe=await Task.Run(()=>RunBridge("probe",song.Url,output,null,requestedQuality));if(cancelQueue){entry.State="已取消";RefreshQueue();break;}var codecs=Success(probe)?ProbeCodecs(probe,song):null;if(codecs==null||codecs.Count==0){entry.State="失败";entry.Error="无法确认歌曲可用音质，请检查后台后重试。";failed++;RefreshQueue();continue;}string trackQuality=requestedQuality;if(!codecs.Contains(trackQuality)){string alternative=trackQuality=="ALAC"?"AAC":"ALAC";if(!codecs.Contains(alternative)){entry.State="失败";entry.Error="这首歌没有所选音质，也没有可用的替代音质。";failed++;RefreshQueue();continue;}bool useAlternative=Notice.Confirm("《"+song.Name+"》没有所选的 "+trackQuality+" 音质。是否使用 "+alternative+" 下载？选择跳过不会下载此歌曲。","音质不可用");if(!useAlternative||cancelQueue){entry.State="已跳过";entry.Error="未使用替代音质。";skippedCount++;RefreshQueue();continue;}trackQuality=alternative;}entry.Phase="准备中";string response=await Task.Run(()=>RunBridge("download",song.Url,output,record=>{object data;var info=record.TryGetValue("data",out data)?Object(data):null;string kind=Get(info,"type");if(kind=="track_error")trackError=true;if(kind=="track_skip")skipped=true;lock(queueProgressGate){latestQueueEntry=entry;latestQueueProgress=record;}},trackQuality));if(Success(response)&&!trackError){entry.Phase="核验格式";entry.Percent=null;RefreshQueue();string actual=await Task.Run(()=>DetectOutputCodec(response,output));entry.Actual=actual==""?"待确认":actual+(String.Equals(actual,trackQuality,StringComparison.OrdinalIgnoreCase)?"":"（与所选不同）");try{entry.FilePath=await Task.Run(()=>AudioArtifact(response,output,song));}catch(Exception pathError){Debug.WriteLine(pathError);}entry.Phase="获取动态封面";RefreshQueue();try{entry.Motion=await Task.Run(()=>SaveMotionArtwork(song,response,output,motionCache));}catch(Exception motionError){entry.Motion="动态封面：获取失败";Debug.WriteLine(motionError);}entry.State=skipped?"已存在":"已完成";entry.Percent=100;completed++;}else{entry.State="失败";entry.Error=trackError?"后台报告该歌曲下载失败。":Failure(response);failed++;}}catch(Exception ex){entry.State="失败";entry.Error=ex.Message;failed++;}finally{RecordHistory(entry,output);}RefreshQueue();}
   for(int i=attempted;i<pending.Count;i++)pending[i].State="已取消";int remaining=pending.Count-attempted;status.Text=cancelQueue?"已停止下载":"下载任务完成";helper.Text="完成 "+completed+" 首，失败 "+failed+" 项"+(skippedCount>0?"，跳过 "+skippedCount+" 首":"")+(remaining>0?"，未处理 "+remaining+" 首":"")+"。";
  }catch(Exception ex){status.Text="下载未完成";helper.Text="请检查保存位置后重试。";Notice.Show(ex.Message,"下载失败");}finally{busy=false;queueRunning=false;cancelQueue=false;UpdateButtons();RefreshQueue();if(historyPage!=null&&historyPage.Visible)LoadHistory();if(historySaveFailed)Notice.Show("部分下载历史未能保存，请检查本机存储权限。歌曲下载结果不受影响。","下载历史未保存");}
 }
 void ChooseFolder(){using(var d=new FolderBrowserDialog{Description="选择歌曲保存位置",SelectedPath=output})if(d.ShowDialog()==DialogResult.OK){output=d.SelectedPath;folderLabel.Text=output;}}
 [STAThread] static void Main(){ServicePointManager.SecurityProtocol=SecurityProtocolType.Tls12;AppFont.Initialize();Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);Application.Run(new MainForm());}
}
